//! Tauri wiring for Machi: window setup, commands and events only (§1.1).
//!
//! All logic lives in `machi-core`; this crate turns it into typed Tauri commands whose
//! TypeScript bindings are generated by tauri-specta into `src/lib/bindings.ts`.

mod commands;

use std::sync::Arc;

use machi_core::app::MachiCore;
use machi_core::secrets::{KEYCHAIN_SERVICE, KeychainStore};
use specta_typescript::Typescript;
use tauri::Manager;
use tauri_specta::{Builder, ErrorHandlingMode, collect_commands};

/// Path of the generated bindings, relative to the `src-tauri` crate directory.
pub const BINDINGS_PATH: &str = "../src/lib/bindings.ts";

/// Builds the tauri-specta registry of every command exposed to the UI.
pub fn specta_builder() -> Builder<tauri::Wry> {
    Builder::<tauri::Wry>::new()
        .error_handling(ErrorHandlingMode::Result)
        .dangerously_cast_bigints_to_number()
        // One TS type per Rust type: `#[serde(default)]` fields stay required in TS.
        .disable_serde_phases()
        .commands(collect_commands![
            commands::platform_info,
            commands::bootstrap,
            commands::list_models,
            commands::provider_statuses,
            commands::test_api_key,
            commands::save_api_key,
            commands::delete_api_key,
            commands::save_settings,
            commands::list_conversations,
            commands::get_conversation,
            commands::search_conversations,
            commands::send_message,
            commands::regenerate_message,
            commands::edit_message,
            commands::stop_generation,
            commands::stop_conversation,
            commands::select_branch,
            commands::delete_message,
            commands::start_compare,
            commands::set_compare_model,
            commands::end_compare,
            commands::rename_conversation,
            commands::set_conversation_pinned,
            commands::update_chat_settings,
            commands::delete_conversation,
            commands::export_conversation,
            commands::export_all,
            commands::delete_all_data,
        ])
}

/// Writes the TypeScript bindings. Used by `cargo run -p machi --example export_bindings`.
pub fn export_bindings(path: &std::path::Path) -> Result<(), String> {
    specta_builder()
        .export(
            Typescript::default().header(
                "// @ts-nocheck\n/* eslint-disable */\n// Generated by tauri-specta from the Rust command definitions. Do not edit.\n",
            ),
            path,
        )
        .map_err(|err| err.to_string())
}

/// Structured local logs only; message content and keys are never logged (§13.3).
fn init_logging() {
    let filter = tracing_subscriber::EnvFilter::try_from_env("MACHI_LOG").unwrap_or_else(|_| {
        tracing_subscriber::EnvFilter::new("machi=info,machi_core=info,machi_lib=info")
    });
    let _ = tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_target(false)
        .try_init();
}

/// Development fallback for keys (§1.3): debug builds only, `.env` at the project root.
#[cfg(debug_assertions)]
fn dev_env() -> Option<machi_core::secrets::DevEnv> {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
    Some(machi_core::secrets::DevEnv::load(&root))
}

#[cfg(not(debug_assertions))]
fn dev_env() -> Option<machi_core::secrets::DevEnv> {
    None
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    init_logging();
    let builder = specta_builder();

    let result = tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            let data_dir = app.path().app_data_dir()?;
            let core = MachiCore::open(
                &data_dir,
                Arc::new(KeychainStore::new(KEYCHAIN_SERVICE)),
                dev_env(),
            )
            .map_err(|e| {
                Box::new(std::io::Error::other(e.to_string())) as Box<dyn std::error::Error>
            })?;
            tracing::info!(data_dir = %data_dir.display(), "machi core ready");
            app.manage(core);
            Ok(())
        })
        .run(tauri::generate_context!());

    if let Err(err) = result {
        eprintln!("machi failed to start: {err}");
        std::process::exit(1);
    }
}
